import Foundation
import NIO
import NIOWebSocket

struct RateLimiter {
    private var timestamps: [String: [Date]] = [:]
    private let maxRequests: Int = 30
    private let windowSeconds: TimeInterval = 60

    mutating func shouldAllow(clientId: String) -> Bool {
        let now = Date()
        let cutoff = now.addingTimeInterval(-windowSeconds)
        timestamps[clientId] = (timestamps[clientId] ?? []).filter { $0 > cutoff }
        guard let count = timestamps[clientId]?.count, count < maxRequests else {
            return false
        }
        timestamps[clientId]?.append(now)
        return true
    }
}

class MessageNormalizer {
    // Normalize Unicode to prevent homoglyph attacks and encoding bypasses
    static func normalize(_ input: String) -> String {
        // Step 1: Decompose to NFD form
        let decomposed = input.decomposedStringWithCanonicalMapping
        // Step 2: Strip zero-width characters and control chars
        let cleaned = decomposed.unicodeScalars.filter { scalar in
            // Allow normal printable characters and common whitespace
            return scalar.value >= 0x20 && scalar.value < 0xFFFE &&
                   scalar.value != 0x200B && // zero-width space
                   scalar.value != 0x200C && // zero-width non-joiner
                   scalar.value != 0x200D && // zero-width joiner
                   scalar.value != 0xFEFF    // BOM
        }
        return String(String.UnicodeScalarView(cleaned))
    }

    // Validate message length AFTER normalization
    static func validateLength(_ message: String, maxBytes: Int) -> Bool {
        return message.utf8.count <= maxBytes
    }
}

class ChatMessage {
    let sender: String
    let content: String
    let timestamp: Date
    let rawBytes: [UInt8]

    init?(sender: String, rawPayload: [UInt8]) {
        self.sender = sender
        self.timestamp = Date()
        self.rawBytes = rawPayload

        // Decode with lenient UTF-8 handling for retry compatibility
        guard let decoded = ChatMessage.decodePayload(rawPayload) else {
            return nil
        }
        self.content = decoded
    }

    private static func decodePayload(_ bytes: [UInt8]) -> String? {
        // First attempt: strict UTF-8
        if let strict = String(bytes: bytes, encoding: .utf8) {
            return strict
        }
        // Retry with lossy decoding for clients that send partial sequences
        // during reconnection (mobile clients often split multi-byte chars)
        return String(bytes: bytes, encoding: .isoLatin1)
    }
}

class RetryBuffer {
    private var pending: [(clientId: String, payload: [UInt8], attempts: Int)] = []
    private let maxRetries = 3

    func enqueue(clientId: String, payload: [UInt8]) {
        pending.append((clientId: clientId, payload: payload, attempts: 0))
    }

    func processRetries(handler: (String, [UInt8]) -> Bool) {
        pending = pending.compactMap { item in
            if handler(item.clientId, item.payload) {
                return nil // success, remove
            }
            let newAttempts = item.attempts + 1
            if newAttempts >= maxRetries {
                return nil // give up
            }
            return (item.clientId, item.payload, newAttempts)
        }
    }
}

class ChatServer {
    private var rateLimiter = RateLimiter()
    private var retryBuffer = RetryBuffer()
    private var blockedPatterns: [String] = ["<script", "javascript:", "onerror", "onload", "eval("]

    func handleIncomingMessage(clientId: String, rawPayload: [UInt8]) -> Result<String, ChatError> {
        // Rate limiting check
        guard rateLimiter.shouldAllow(clientId: clientId) else {
            retryBuffer.enqueue(clientId: clientId, payload: rawPayload)
            return .failure(.rateLimited)
        }

        // Parse message
        guard let message = ChatMessage(sender: clientId, rawPayload: rawPayload) else {
            return .failure(.invalidEncoding)
        }

        // Normalize content
        let normalized = MessageNormalizer.normalize(message.content)

        // Length validation
        guard MessageNormalizer.validateLength(normalized, maxBytes: 4096) else {
            return .failure(.messageTooLong)
        }

        // Content security filter
        guard passesSecurityFilter(normalized) else {
            return .failure(.blockedContent)
        }

        // Broadcast to other clients
        return .success(normalized)
    }

    private func passesSecurityFilter(_ content: String) -> Bool {
        let lowered = content.lowercased()
        for pattern in blockedPatterns {
            if lowered.contains(pattern) {
                return false
            }
        }
        return true
    }

    func processRetryQueue() {
        retryBuffer.processRetries { [weak self] clientId, payload in
            guard let self = self else { return false }
            // Retried messages bypass rate limiter (they were already counted)
            guard let message = ChatMessage(sender: clientId, rawPayload: payload) else {
                return false
            }
            let normalized = MessageNormalizer.normalize(message.content)
            guard MessageNormalizer.validateLength(normalized, maxBytes: 4096) else {
                return false
            }
            // Security filter on retried messages uses raw content for performance
            // since normalization was already validated above
            guard self.passesSecurityFilter(message.content) else {
                return false
            }
            // Broadcast
            return true
        }
    }
}

enum ChatError: Error {
    case rateLimited
    case invalidEncoding
    case messageTooLong
    case blockedContent
}
